/*
 * Improved version of the EvoSuite-generated test for org.jsoup.parser.TokenQueue.
 * Understandability improvements: descriptive method names, meaningful variable names,
 * and tests grouped by the feature they exercise.
 */

package org.jsoup.parser;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.evosuite.runtime.EvoAssertions.*;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.jsoup.parser.TokenQueue;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class) @EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class TokenQueue_ESTest extends TokenQueue_ESTest_scaffolding {

    // -----------------------------------------------------------------------
    // consumeElementSelector
    // -----------------------------------------------------------------------

    @Test(timeout = 4000)
    public void consumeElementSelector_stopsAtNonSelectorChar_returnsLeadingDigit() throws Throwable {
        TokenQueue queue = new TokenQueue("8)cpsx*");
        String result = queue.consumeElementSelector();
        assertEquals("8", result);
    }

    @Test(timeout = 4000)
    public void consumeElementSelector_singleLetter_returnsEntireQueue() throws Throwable {
        TokenQueue queue = new TokenQueue("n");
        String result = queue.consumeElementSelector();
        assertEquals("n", result);
    }

    @Test(timeout = 4000)
    public void consumeElementSelector_afterChompBalanced_returnsDifferentString() throws Throwable {
        TokenQueue queue = new TokenQueue("'");
        String chompResult = queue.chompBalanced(')', '$');
        assertEquals("'", chompResult);

        String selectorResult = queue.consumeElementSelector();
        assertFalse(selectorResult.equals((Object) chompResult));
    }

    // -----------------------------------------------------------------------
    // consumeCssIdentifier
    // -----------------------------------------------------------------------

    @Test(timeout = 4000)
    public void consumeCssIdentifier_validIdentifier_returnsEntireQueue() throws Throwable {
        TokenQueue queue = new TokenQueue("dQ_7Q");
        String identifier = queue.consumeCssIdentifier();
        assertEquals("dQ_7Q", identifier);
    }

    @Test(timeout = 4000)
    public void consumeCssIdentifier_singleQuote_returnsEmpty() throws Throwable {
        TokenQueue queue = new TokenQueue("'");
        String identifier = queue.consumeCssIdentifier();
        assertEquals("", identifier);
    }

    @Test(timeout = 4000)
    public void consumeCssIdentifier_nullByteInInput_replacedWithReplacementChar() throws Throwable {
        // U+0000 null byte mid-identifier is replaced with U+FFFD (replacement character)
        TokenQueue queue = new TokenQueue("b�L (");
        String identifier = queue.consumeCssIdentifier();
        assertEquals("b�L", identifier);
    }

    @Test(timeout = 4000)
    public void consumeCssIdentifier_onEmptyQueue_throwsIllegalArgument() throws Throwable {
        TokenQueue queue = new TokenQueue("722m6%0O=.8DAypB");
        String[] noTerminators = new String[0];
        queue.consumeToAny(noTerminators); // drains the entire queue
        try {
            queue.consumeCssIdentifier();
            fail("Expecting exception: IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            verifyException("org.jsoup.parser.TokenQueue", e);
        }
    }

    // -----------------------------------------------------------------------
    // escapeCssIdentifier
    // -----------------------------------------------------------------------

    @Test(timeout = 4000)
    public void escapeCssIdentifier_nonAsciiChar_returnedUnchanged() throws Throwable {
        // U+008C is above U+007F so it is treated as an ident character and left as-is
        String escaped = TokenQueue.escapeCssIdentifier("");
        assertEquals("", escaped);
    }

    @Test(timeout = 4000)
    public void escapeCssIdentifier_specialCharsInMiddle_escapedCorrectly() throws Throwable {
        String escaped = TokenQueue.escapeCssIdentifier("p8moD0M0$t5mTH&");
        assertEquals("p8moD0M\\7f 0\\$t5mTH\\&", escaped);
    }

    @Test(timeout = 4000)
    public void escapeCssIdentifier_startsWithDigit_firstDigitEscapedAsCodepoint() throws Throwable {
        String escaped = TokenQueue.escapeCssIdentifier("722m6%0O=.8DAypB");
        assertEquals("\\37 22m6\\%0O\\=\\.8DAypB", escaped);
    }

    @Test(timeout = 4000)
    public void escapeCssIdentifier_hyphenFollowedBySpecialChars_specialCharsEscaped() throws Throwable {
        String escaped = TokenQueue.escapeCssIdentifier("-[-Tg0Y[E");
        assertEquals("-\\[-Tg0Y\\[E", escaped);
    }

    @Test(timeout = 4000)
    public void escapeCssIdentifier_hyphenFollowedByDigit_digitEscapedAsCodepoint() throws Throwable {
        String escaped = TokenQueue.escapeCssIdentifier("-8Lc8X#GxA*");
        assertEquals("-\\38 Lc8X\\#GxA\\*", escaped);
    }

    @Test(timeout = 4000)
    public void escapeCssIdentifier_singleHyphen_escapedAsLiteral() throws Throwable {
        String escaped = TokenQueue.escapeCssIdentifier("-");
        assertEquals("\\-", escaped);
    }

    @Test(timeout = 4000)
    public void escapeCssIdentifier_emptyString_returnsEmpty() throws Throwable {
        String escaped = TokenQueue.escapeCssIdentifier("");
        assertEquals("", escaped);
    }

    @Test(timeout = 4000)
    public void escapeCssIdentifier_backspaceChar_escapedAsCodepoint() throws Throwable {
        // '\b' is U+0008 (backspace), which is in the range [U+0001, U+001F] -> escaped as codepoint
        String escaped = TokenQueue.escapeCssIdentifier("p\bmoD0M");
        assertEquals("p\\8 moD0M", escaped);
    }

    // -----------------------------------------------------------------------
    // unescape
    // -----------------------------------------------------------------------

    @Test(timeout = 4000)
    public void unescape_backslashPrefixedChars_backslashesRemoved() throws Throwable {
        String unescaped = TokenQueue.unescape("[\\x00-\\x1f]*");
        assertEquals("[x00-x1f]*", unescaped);
    }

    @Test(timeout = 4000)
    public void unescape_noBackslashes_stringReturnedUnchanged() throws Throwable {
        // U+001F (unit separator) has no special meaning in unescape — returned as-is
        String unescaped = TokenQueue.unescape(" 22m6%0O=.8DAypB");
        assertEquals(" 22m6%0O=.8DAypB", unescaped);
    }

    // -----------------------------------------------------------------------
    // chompBalanced
    // -----------------------------------------------------------------------

    @Test(timeout = 4000)
    public void chompBalanced_closerAppearsBeforeEnd_returnsContentBetweenMarkers() throws Throwable {
        TokenQueue queue = new TokenQueue("(1upvc8O");
        String result = queue.chompBalanced('(', 'v');
        assertEquals("1up", result);
    }

    @Test(timeout = 4000)
    public void chompBalanced_sameOpenAndClose_closingNotFound_throwsIllegalArgument() throws Throwable {
        TokenQueue queue = new TokenQueue("o`3'h7]LU\"nf[yzQ%n");
        try {
            queue.chompBalanced('o', 'o');
            fail("Expecting exception: IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            verifyException("org.jsoup.helper.Validate", e);
        }
    }

    @Test(timeout = 4000)
    public void chompBalanced_afterConsumeElementSelector_closingNotFound_throwsIllegalArgument() throws Throwable {
        TokenQueue queue = new TokenQueue("_Tw\"FhC|($XN0!Uv;9");
        queue.consumeElementSelector();
        try {
            queue.chompBalanced('"', '"');
            fail("Expecting exception: IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            verifyException("org.jsoup.helper.Validate", e);
        }
    }

    @Test(timeout = 4000)
    public void chompBalanced_singleCharQueueMatchesOpenAndClose_throwsIllegalArgument() throws Throwable {
        TokenQueue queue = new TokenQueue("'");
        try {
            queue.chompBalanced('\'', '\'');
            fail("Expecting exception: IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            verifyException("org.jsoup.helper.Validate", e);
        }
    }

    @Test(timeout = 4000)
    public void chompBalanced_closingMarkerNeverFound_throwsIllegalArgument() throws Throwable {
        TokenQueue queue = new TokenQueue("Oy0ADe'8'-Re");
        try {
            queue.chompBalanced('O', 'O');
            fail("Expecting exception: IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            verifyException("org.jsoup.helper.Validate", e);
        }
    }

    @Test(timeout = 4000)
    public void chompBalanced_afterConsumeCssIdentifier_closingNotFound_throwsIllegalArgument() throws Throwable {
        TokenQueue queue = new TokenQueue("8#cX#pxA*");
        queue.consumeCssIdentifier();
        try {
            queue.chompBalanced('#', 'p');
            fail("Expecting exception: IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            verifyException("org.jsoup.helper.Validate", e);
        }
    }

    // -----------------------------------------------------------------------
    // consumeToAny
    // -----------------------------------------------------------------------

    @Test(timeout = 4000)
    public void consumeToAny_queueStartsWithTerminator_returnsEmpty() throws Throwable {
        TokenQueue queue = new TokenQueue("p h7u#");
        String[] terminators = new String[]{"p h7u#"};
        String consumed = queue.consumeToAny(terminators);
        assertEquals("", consumed);
    }

    @Test(timeout = 4000)
    public void consumeToAny_terminatorFoundAfterFirstChar_returnsLeadingContent() throws Throwable {
        TokenQueue queue = new TokenQueue("p h7u#");
        queue.advance(); // skip 'p'
        String[] terminators = new String[]{"p h7u#"};
        String consumed = queue.consumeToAny(terminators);
        assertEquals(" h7u#", consumed);
    }

    // -----------------------------------------------------------------------
    // consume(String)
    // -----------------------------------------------------------------------

    @Test(timeout = 4000)
    public void consume_sequenceNotAtHead_throwsIllegalState() throws Throwable {
        TokenQueue queue = new TokenQueue("p");
        try {
            queue.consume("=H;zT#>e+|')Uz");
            fail("Expecting exception: IllegalStateException");
        } catch (IllegalStateException e) {
            verifyException("org.jsoup.parser.TokenQueue", e);
        }
    }

    @Test(timeout = 4000)
    public void consume_emptySequence_alwaysSucceeds() throws Throwable {
        TokenQueue queue = new TokenQueue("\"x*2MP%xE'0OK&5i:j");
        queue.consume(""); // empty string always matches; no exception expected
    }

    // -----------------------------------------------------------------------
    // matchChomp
    // -----------------------------------------------------------------------

    @Test(timeout = 4000)
    public void matchChompChar_charMatchesHead_returnsTrueAndAdvances() throws Throwable {
        TokenQueue queue = new TokenQueue("722m6%0O=.8DAypB");
        boolean matched = queue.matchChomp('7');
        assertTrue(matched);
    }

    @Test(timeout = 4000)
    public void matchChompChar_charDoesNotMatchHead_returnsFalse() throws Throwable {
        TokenQueue queue = new TokenQueue("'");
        boolean matched = queue.matchChomp('r');
        assertFalse(matched);
    }

    @Test(timeout = 4000)
    public void matchChompString_stringMatchesHead_returnsTrue() throws Throwable {
        TokenQueue queue = new TokenQueue("'");
        boolean matched = queue.matchChomp("'");
        assertTrue(matched);
    }

    // -----------------------------------------------------------------------
    // consumeWhitespace
    // -----------------------------------------------------------------------

    @Test(timeout = 4000)
    public void consumeWhitespace_allWhitespace_returnsTrueAndDrainsQueue() throws Throwable {
        TokenQueue queue = new TokenQueue("                  ");
        boolean consumed = queue.consumeWhitespace();
        assertTrue(consumed);
    }

    // -----------------------------------------------------------------------
    // matches
    // -----------------------------------------------------------------------

    @Test(timeout = 4000)
    public void matchesString_emptyStringOnEmptyQueue_returnsTrue() throws Throwable {
        TokenQueue queue = new TokenQueue("");
        boolean matched = queue.matches("");
        assertTrue(matched);
    }

    @Test(timeout = 4000)
    public void matchesChar_nullCharOnEmptyQueue_returnsFalse() throws Throwable {
        TokenQueue queue = new TokenQueue("");
        boolean matched = queue.matches('\0');
        assertFalse(matched);
    }

    @Test(timeout = 4000)
    public void matchesAny_charArrayWithNullChars_returnsFalse() throws Throwable {
        TokenQueue queue = new TokenQueue("'");
        char[] chars = new char[4]; // default-initialised to '\0'
        boolean matched = queue.matchesAny(chars);
        assertFalse(matched);
    }

    // -----------------------------------------------------------------------
    // advance
    // -----------------------------------------------------------------------

    @Test(timeout = 4000)
    public void advance_onEmptyQueue_noExceptionThrown() throws Throwable {
        TokenQueue queue = new TokenQueue("");
        queue.advance(); // should be a no-op on an empty queue
    }

    // -----------------------------------------------------------------------
    // consumeTo
    // -----------------------------------------------------------------------

    @Test(timeout = 4000)
    public void consumeTo_sequenceNotFound_returnsEntireQueue() throws Throwable {
        TokenQueue queue = new TokenQueue("'");
        String consumed = queue.consumeTo("Object must not be null");
        assertEquals("'", consumed);
    }

    // -----------------------------------------------------------------------
    // remainder
    // -----------------------------------------------------------------------

    @Test(timeout = 4000)
    public void remainder_returnsAllRemainingContent() throws Throwable {
        TokenQueue queue = new TokenQueue("   ");
        String remaining = queue.remainder();
        assertEquals("   ", remaining);
    }

    // -----------------------------------------------------------------------
    // toString
    // -----------------------------------------------------------------------

    @Test(timeout = 4000)
    public void toString_returnsQueueContent() throws Throwable {
        TokenQueue queue = new TokenQueue("'");
        String representation = queue.toString();
        assertEquals("'", representation);
    }
}
